public class MultiStepPipeline {
    public static int multiplyByTwo(int n) {
        System.out.println("  -> Inside multiplyByTwo: n = " + n);
        return n * 2;
    }

    public static int processOrder(int units) {
        System.out.println("-> Entering processOrder: units = " + units);
        // Method calls another method
        int doubled = multiplyByTwo(units);
        System.out.println("-> processOrder received doubled = " + doubled);
        return doubled + 10;
    }

    public static void main(String[] args) {
        System.out.println("Main starts");
        int finalResult = processOrder(5);
        System.out.println("Main finished: result = " + finalResult);
    }
}

