    public static double calcBaseSalary(double hourlyRate, int hours) {
        return hourlyRate * hours;
    }

    public static double calcGrossSalary(double hourlyRate, int hours, double bonus) {
        return calcBaseSalary(hourlyRate, hours) + bonus;
