practiceProblems.solutionCode:
public class Main {
    public static boolean isEven(int n) {
        return n % 2 == 0;
    }

    public static int countEvensInRange(int start, int end) {
        int count = 0;
        for (int i = start; i <= end; i++) {
            if (isEven(i)) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int count = countEvensInRange(1, 10);
        System.out.println("Evens in 1..10: " + count);
    }
}

