practiceProblems.solutionCode:
public class Main {
    public static String cleanSpaces(String s) {
        return s.trim();
    }

    public static String toTitleCase(String s) {
        return s.toUpperCase();
    }

    public static String formatTag(String s) {
        return "#" + s;
    }

    public static void main(String[] args) {
        String input = "  java methods  ";
        String tag = formatTag(toTitleCase(cleanSpaces(input)));
        System.out.println("Formatted Tag: " + tag);
    }
}

